                    let mut g_s = a_sub;
                    g_s[2][1] -= N_I[2][0] * j_dev[0] * N_V[0][1];
                    g_s[2][2] -= N_I[2][0] * j_dev[0] * N_V[0][2];
                    g_s[4][1] -= N_I[4][0] * j_dev[0] * N_V[0][1];
                    g_s[4][2] -= N_I[4][0] * j_dev[0] * N_V[0][2];
                    g_s[2][1] -= N_I[2][0] * j_dev[1] * N_V[1][1];
                    g_s[2][4] -= N_I[2][0] * j_dev[1] * N_V[1][4];
                    g_s[4][1] -= N_I[4][0] * j_dev[1] * N_V[1][1];
                    g_s[4][4] -= N_I[4][0] * j_dev[1] * N_V[1][4];
                    g_s[1][1] -= N_I[1][1] * j_dev[14] * N_V[0][1];
                    g_s[1][2] -= N_I[1][1] * j_dev[14] * N_V[0][2];
                    g_s[2][1] -= N_I[2][1] * j_dev[14] * N_V[0][1];
                    g_s[2][2] -= N_I[2][1] * j_dev[14] * N_V[0][2];
                    g_s[1][1] -= N_I[1][1] * j_dev[15] * N_V[1][1];
                    g_s[1][4] -= N_I[1][1] * j_dev[15] * N_V[1][4];
                    g_s[2][1] -= N_I[2][1] * j_dev[15] * N_V[1][1];
                    g_s[2][4] -= N_I[2][1] * j_dev[15] * N_V[1][4];
                    g_s[2][2] -= N_I[2][2] * j_dev[30] * N_V[2][2];
                    g_s[2][6] -= N_I[2][2] * j_dev[30] * N_V[2][6];
                    g_s[5][2] -= N_I[5][2] * j_dev[30] * N_V[2][2];
                    g_s[5][6] -= N_I[5][2] * j_dev[30] * N_V[2][6];
                    g_s[2][5] -= N_I[2][2] * j_dev[31] * N_V[3][5];
                    g_s[2][6] -= N_I[2][2] * j_dev[31] * N_V[3][6];
                    g_s[5][5] -= N_I[5][2] * j_dev[31] * N_V[3][5];
                    g_s[5][6] -= N_I[5][2] * j_dev[31] * N_V[3][6];
                    g_s[2][2] -= N_I[2][3] * j_dev[44] * N_V[2][2];
                    g_s[2][6] -= N_I[2][3] * j_dev[44] * N_V[2][6];
                    g_s[6][2] -= N_I[6][3] * j_dev[44] * N_V[2][2];
                    g_s[6][6] -= N_I[6][3] * j_dev[44] * N_V[2][6];
                    g_s[2][5] -= N_I[2][3] * j_dev[45] * N_V[3][5];
                    g_s[2][6] -= N_I[2][3] * j_dev[45] * N_V[3][6];
                    g_s[6][5] -= N_I[6][3] * j_dev[45] * N_V[3][5];
                    g_s[6][6] -= N_I[6][3] * j_dev[45] * N_V[3][6];
                    g_s[7][4] -= N_I[7][4] * j_dev[60] * N_V[4][4];
                    g_s[7][7] -= N_I[7][4] * j_dev[60] * N_V[4][7];
                    g_s[10][4] -= N_I[10][4] * j_dev[60] * N_V[4][4];
                    g_s[10][7] -= N_I[10][4] * j_dev[60] * N_V[4][7];
                    g_s[7][4] -= N_I[7][4] * j_dev[61] * N_V[5][4];
                    g_s[7][10] -= N_I[7][4] * j_dev[61] * N_V[5][10];
                    g_s[10][4] -= N_I[10][4] * j_dev[61] * N_V[5][4];
                    g_s[10][10] -= N_I[10][4] * j_dev[61] * N_V[5][10];
                    g_s[4][4] -= N_I[4][5] * j_dev[74] * N_V[4][4];
                    g_s[4][7] -= N_I[4][5] * j_dev[74] * N_V[4][7];
                    g_s[7][4] -= N_I[7][5] * j_dev[74] * N_V[4][4];
                    g_s[7][7] -= N_I[7][5] * j_dev[74] * N_V[4][7];
                    g_s[4][4] -= N_I[4][5] * j_dev[75] * N_V[5][4];
                    g_s[4][10] -= N_I[4][5] * j_dev[75] * N_V[5][10];
                    g_s[7][4] -= N_I[7][5] * j_dev[75] * N_V[5][4];
                    g_s[7][10] -= N_I[7][5] * j_dev[75] * N_V[5][10];
                    g_s[14][12] -= N_I[14][6] * j_dev[90] * N_V[6][12];
                    g_s[14][15] -= N_I[14][6] * j_dev[90] * N_V[6][15];
                    g_s[15][12] -= N_I[15][6] * j_dev[90] * N_V[6][12];
                    g_s[15][15] -= N_I[15][6] * j_dev[90] * N_V[6][15];
                    g_s[14][12] -= N_I[14][6] * j_dev[91] * N_V[7][12];
                    g_s[14][14] -= N_I[14][6] * j_dev[91] * N_V[7][14];
                    g_s[15][12] -= N_I[15][6] * j_dev[91] * N_V[7][12];
                    g_s[15][14] -= N_I[15][6] * j_dev[91] * N_V[7][14];
                    g_s[12][12] -= N_I[12][7] * j_dev[104] * N_V[6][12];
                    g_s[12][15] -= N_I[12][7] * j_dev[104] * N_V[6][15];
                    g_s[15][12] -= N_I[15][7] * j_dev[104] * N_V[6][12];
                    g_s[15][15] -= N_I[15][7] * j_dev[104] * N_V[6][15];
                    g_s[12][12] -= N_I[12][7] * j_dev[105] * N_V[7][12];
                    g_s[12][14] -= N_I[12][7] * j_dev[105] * N_V[7][14];
                    g_s[15][12] -= N_I[15][7] * j_dev[105] * N_V[7][12];
                    g_s[15][14] -= N_I[15][7] * j_dev[105] * N_V[7][14];
                    g_s[3][3] -= N_I[3][8] * j_dev[120] * N_V[8][3];
                    g_s[3][14] -= N_I[3][8] * j_dev[120] * N_V[8][14];
                    g_s[15][3] -= N_I[15][8] * j_dev[120] * N_V[8][3];
                    g_s[15][14] -= N_I[15][8] * j_dev[120] * N_V[8][14];
                    g_s[3][14] -= N_I[3][8] * j_dev[121] * N_V[9][14];
                    g_s[3][15] -= N_I[3][8] * j_dev[121] * N_V[9][15];
                    g_s[15][14] -= N_I[15][8] * j_dev[121] * N_V[9][14];
                    g_s[15][15] -= N_I[15][8] * j_dev[121] * N_V[9][15];
                    g_s[3][3] -= N_I[3][9] * j_dev[134] * N_V[8][3];
                    g_s[3][14] -= N_I[3][9] * j_dev[134] * N_V[8][14];
                    g_s[14][3] -= N_I[14][9] * j_dev[134] * N_V[8][3];
                    g_s[14][14] -= N_I[14][9] * j_dev[134] * N_V[8][14];
                    g_s[3][14] -= N_I[3][9] * j_dev[135] * N_V[9][14];
                    g_s[3][15] -= N_I[3][9] * j_dev[135] * N_V[9][15];
                    g_s[14][14] -= N_I[14][9] * j_dev[135] * N_V[9][14];
                    g_s[14][15] -= N_I[14][9] * j_dev[135] * N_V[9][15];
                    g_s[16][10] -= N_I[16][10] * j_dev[150] * N_V[10][10];
                    g_s[16][17] -= N_I[16][10] * j_dev[150] * N_V[10][17];
